<script setup lang="ts">
import {externalSubscriptionSchema} from '@brightloop/shared'
interface External { id:string;name:string;amount:number;interval:string;nextRenewal:string;status:string;managementUrl:string;notes:string }
interface Candidate {receiptDate?:string|null;sourceUrl?:string;name:string;amount:number|null;interval:string;nextRenewal:string;status:string;managementUrl:string;notes:string;evidence:string;confidence:string}
const api=useApi(),toast=useToast(),route=useRoute()
const {data:gmail,refresh:refreshGmail}=await useFetch<{connected:boolean;email?:string}>('/api/gmail')
const mailBusy=ref(false),mailError=ref(''),mailSummary=ref('')
const scanned=ref(0),stopRequested=ref(false)
async function scanGmail(){
 if(mailBusy.value)return
 mailBusy.value=true;mailError.value='';scanned.value=0;stopRequested.value=false;candidates.value=[]
 let pageToken:string|undefined
 const found=new Map<string,Candidate>()
 try{
  do{
   const result=await api<{candidates:Candidate[];scanned:number;nextPageToken:string|null}>('/gmail/scan',{method:'POST',body:{pageToken}})
   scanned.value+=result.scanned
   for(const c of result.candidates){const id=c.name.toLowerCase();const previous=found.get(id);if(!previous||Date.parse(c.receiptDate||'')>Date.parse(previous.receiptDate||''))found.set(id,c)}
   candidates.value=[...found.values()]
   pageToken=result.nextPageToken||undefined
   mailSummary.value=`${scanned.value.toLocaleString()} emails checked · ${found.size} subscription suggestions found.`
  }while(pageToken&&!stopRequested.value)
  mailSummary.value+=pageToken?' Scan stopped; you can review what was found.':' Mailbox scan complete.'
 }catch(e){mailError.value=errorMessage(e)}finally{mailBusy.value=false}
}
onBeforeUnmount(()=>{stopRequested.value=true})
async function disconnectGmail(){mailBusy.value=true;try{await api('/gmail',{method:'DELETE'});await refreshGmail();candidates.value=[];mailSummary.value=''}catch(e){mailError.value=errorMessage(e)}finally{mailBusy.value=false}}
onMounted(()=>{if(route.query.gmail_connected==='1')void scanGmail();if(route.query.gmail_error)mailError.value=route.query.gmail_error==='account'?'Choose the same Google account used for your Brightloop login.':'Gmail permission could not be granted. Enable Gmail API in Google Cloud and grant read access, then reconnect.'})
const {data,error,status,refresh}=await useFetch<{items:External[];totals:{monthly:number;yearly:number;active:number}}>('/api/external-subscriptions')
const open=ref(false),editing=ref(''),busy=ref(false),formError=ref('')
const empty=()=>({name:'',amount:'',interval:'MONTHLY',nextRenewal:new Date().toISOString().slice(0,10),status:'ACTIVE',managementUrl:'',notes:''})
const form=ref(empty())
function edit(item?:External){editing.value=item?.id||'';formError.value='';form.value=item?{name:item.name,amount:String(item.amount/100),interval:item.interval,nextRenewal:item.nextRenewal.slice(0,10),status:item.status,managementUrl:item.managementUrl,notes:item.notes}:empty();open.value=true}
function review(c:Candidate){const existing=data.value?.items.find(i=>i.name.toLowerCase()===c.name.toLowerCase());editing.value=existing?.id||'';formError.value='';form.value={...empty(),...c,amount:c.amount==null?(existing?String(existing.amount/100):''):String(c.amount),status:existing?.status||c.status,notes:existing?.notes||c.notes};open.value=true}
async function save(){busy.value=true;formError.value='';try{const parsed=externalSubscriptionSchema.safeParse(form.value);if(!parsed.success){formError.value=parsed.error.issues.map(i=>i.message).join('; ');return}await api(`/external-subscriptions${editing.value?'/'+editing.value:''}`,{method:editing.value?'PUT':'POST',body:form.value});open.value=false;candidates.value=candidates.value.filter(c=>c.name!==form.value.name);await refresh();toast.add({title:'Subscription saved',color:'success'})}catch(e){formError.value=errorMessage(e)}finally{busy.value=false}}
const removing=ref<External|null>(null)
async function remove(){if(!removing.value)return;busy.value=true;try{await api(`/external-subscriptions/${removing.value.id}`,{method:'DELETE'});removing.value=null;await refresh()}catch(e){toast.add({title:errorMessage(e),color:'error'})}finally{busy.value=false}}
const candidates=ref<Candidate[]>([])
const due=computed(()=>data.value?.items.filter(i=>i.status==='ACTIVE'&&Date.parse(i.nextRenewal)<=Date.now()+7*86400000)||[])
function renewalLabel(value:string){const days=Math.ceil((Date.parse(value)-Date.now())/86400000);return days<0?'Date passed — review renewal':days===0?'Renews today':`Renews in ${days} day${days===1?'':'s'}`}
</script>
<template><div class="page"><div class="page-head"><div><p class="text-primary text-xs uppercase tracking-widest mb-2">Personal spending</p><h1>My external subscriptions</h1><p>Track Netflix, Prime, apps and other services you pay for.</p></div><UButton icon="i-lucide-plus" @click="edit()">Add subscription</UButton></div><UAlert v-if="error" color="error" :title="errorMessage(error)" class="mb-5"><template #actions><UButton @click="refresh()">Retry</UButton></template></UAlert><div class="grid sm:grid-cols-3 gap-4 mb-6"><UCard><p class="text-sm text-muted">Estimated monthly cost</p><p class="text-3xl font-semibold mt-3">{{money(data?.totals.monthly)}}</p></UCard><UCard><p class="text-sm text-muted">Estimated yearly cost</p><p class="text-3xl font-semibold mt-3">{{money(data?.totals.yearly)}}</p></UCard><UCard><p class="text-sm text-muted">Active subscriptions</p><p class="text-3xl font-semibold mt-3">{{data?.totals.active||0}}</p></UCard></div><UAlert v-if="due.length" icon="i-lucide-calendar-clock" color="warning" :title="`${due.length} renewal date(s) need attention`" description="Due within 7 days or already passed. Review the provider's billing page and update your tracked date." class="mb-6"/><div v-if="status==='pending'" class="grid md:grid-cols-2 gap-4"><USkeleton v-for="n in 2" :key="n" class="h-52"/></div><div v-else-if="!data?.items.length&&!error" class="border border-dashed border-default rounded-xl text-center p-12 mb-6"><UIcon name="i-lucide-wallet-cards" class="size-10 text-muted mb-3"/><h2 class="font-semibold text-lg">Make recurring spending visible</h2><p class="text-muted text-sm mt-2">Connect Gmail to discover subscriptions, or add one manually.</p></div><div class="grid md:grid-cols-2 xl:grid-cols-3 gap-5 mb-8"><UCard v-for="item in data?.items" :key="item.id"><div class="flex justify-between items-start gap-3"><h2 class="font-semibold text-lg">{{item.name}}</h2><UBadge :color="item.status==='ACTIVE'?'success':'neutral'" variant="subtle">{{item.status==='ACTIVE'?'Active':'Cancelled'}}</UBadge></div><p class="text-2xl font-semibold mt-5">{{money(item.amount)}} <span class="text-sm font-normal text-muted">/ {{item.interval.toLowerCase()}}</span></p><p class="text-sm mt-3" :class="item.status==='ACTIVE'?'text-primary':'text-muted'">{{item.status==='ACTIVE'?renewalLabel(item.nextRenewal):'Not included in cost estimates'}}</p><p class="text-xs text-muted mt-1">Tracked date: {{date(item.nextRenewal)}}</p><p v-if="item.notes" class="text-sm text-muted mt-3 whitespace-pre-wrap">{{item.notes}}</p><div class="flex flex-wrap gap-2 mt-5"><UButton v-if="item.managementUrl" :to="item.managementUrl" target="_blank" external rel="noopener noreferrer" color="neutral" variant="outline" size="xs" trailing-icon="i-lucide-external-link">Manage at provider</UButton><UButton variant="ghost" size="xs" @click="edit(item)">Edit</UButton><UButton color="error" variant="ghost" size="xs" @click="removing=item">Remove</UButton></div></UCard></div><UCard class="mb-6"><template #header><div class="flex gap-3 items-center"><UIcon name="i-lucide-mail" class="size-5 text-primary"/><div><h2 class="font-semibold">Find subscriptions in Gmail</h2><p class="text-sm text-muted mt-1">Connect your own mailbox and review receipt-based suggestions.</p></div></div></template><div class="space-y-4"><UAlert v-if="mailError" color="error" :title="mailError"/><p class="text-sm text-muted">Separate Google consent is required for read-only Gmail access. We check your mailbox history in small batches, looking for subscription receipts. Spam and Trash are excluded. Email content is not sent to AI, and subscriptions are saved only after your review.</p><div class="flex flex-wrap items-center gap-3"><template v-if="gmail?.connected"><UBadge color="success" variant="subtle">{{gmail.email}}</UBadge><UButton icon="i-lucide-scan-search" :loading="mailBusy" @click="scanGmail">Scan mailbox</UButton><UButton v-if="mailBusy" color="neutral" variant="outline" :disabled="stopRequested" @click="stopRequested=true">{{stopRequested?'Stopping…':'Stop scan'}}</UButton><UButton color="neutral" variant="ghost" :disabled="mailBusy" @click="disconnectGmail">Disconnect Gmail</UButton></template><UButton v-else to="/api/auth/google?gmail=1" external icon="i-lucide-mail">Connect Gmail</UButton></div><UProgress v-if="mailBusy" aria-label="Scanning mailbox"/><p v-if="mailSummary" class="text-sm text-muted">{{mailSummary}}</p><p v-if="gmail?.connected" class="text-xs text-muted">Disconnect removes the stored connection from Brightloop. You can also revoke this app in your Google Account permissions.</p></div></UCard><UCard v-if="candidates.length" class="mt-6"><template #header><h2 class="font-semibold">Review subscription suggestions</h2></template><div v-for="candidate in candidates" :key="candidate.name" class="flex flex-wrap justify-between items-center gap-4 border-t border-default mt-5 pt-5"><div><p class="font-medium">{{candidate.name}} · {{candidate.amount==null?'Amount needs review':money(candidate.amount*100)}}</p><p class="text-sm text-muted mt-1 max-w-xl">{{candidate.evidence}}</p></div><div class="flex gap-2"><UButton v-if="candidate.sourceUrl" :to="candidate.sourceUrl" target="_blank" external rel="noopener noreferrer" color="neutral" variant="ghost" size="sm">View receipt</UButton><UButton size="sm" @click="review(candidate)">{{data?.items.some(i=>i.name.toLowerCase()===candidate.name.toLowerCase())?'Review update':'Review & add'}}</UButton></div></div></UCard><p class="text-xs text-muted mt-4">These are personal tracking records. Changes here do not cancel a provider subscription or create Brightloop invoices.</p>
<UModal v-model:open="open" :title="editing?'Edit subscription':'Add external subscription'"><template #body><form class="space-y-4" @submit.prevent="save"><UAlert v-if="formError" color="error" :title="formError"/><UFormField label="Service name"><UInput v-model="form.name" placeholder="e.g. Netflix" class="w-full"/></UFormField><div class="grid grid-cols-2 gap-4"><UFormField label="Amount (₹)"><UInput v-model="form.amount" type="number" min="0" step="0.01" class="w-full"/></UFormField><UFormField label="Billing interval"><USelect v-model="form.interval" :items="['MONTHLY','YEARLY','WEEKLY']" class="w-full"/></UFormField></div><UFormField label="Next renewal"><UInput v-model="form.nextRenewal" type="date" class="w-full"/></UFormField><UFormField label="Status"><USelect v-model="form.status" :items="['ACTIVE','CANCELLED']" class="w-full"/></UFormField><UFormField label="Provider management URL (HTTPS, optional)"><UInput v-model="form.managementUrl" type="url" placeholder="https://…" class="w-full"/></UFormField><UFormField label="Notes"><UTextarea v-model="form.notes" class="w-full"/></UFormField><UButton type="submit" block :loading="busy">Save subscription</UButton></form></template></UModal><UModal :open="!!removing" title="Remove tracked subscription?" description="This removes the tracking record only. It does not cancel your provider subscription." @update:open="value=>{if(!value)removing=null}"><template #footer><UButton variant="ghost" color="neutral" @click="removing=null">Keep record</UButton><UButton color="error" :loading="busy" @click="remove">Remove record</UButton></template></UModal></div></template>
